types.Config:
public class Config
{
    /* One declaration of the settings, shared by every Flow that calls this one.
       Consumers reach these fields as ExternalConfig, never as a copy. */

    /* Exchange rates published by the European Central Bank. Open, no key. */
    public string ratesUrl { get; set; }

    /* A list endpoint that understands _start and _limit, for the paging example. */
    public string listUrl { get; set; }

    /* Both sources are public, so these stay empty. Real deployments fill them
       here, in one place, and no consuming Flow ever holds a credential. */
    public string login { get; set; }
    public string password { get; set; }

    public int pageSize { get; set; }
}
